// ApplyRefreshInterval changes the per-feed refresh interval (in minutes)
// and reschedules the next check when the value changes.
func (f *Feed) ApplyRefreshInterval(minutes int) {
	if minutes < 0 {
		minutes = 0
	}
	if f.RefreshInterval == minutes {
		return
	}
	f.RefreshInterval = minutes
	if minutes > 0 {
		f.NextCheckAt = time.Now().Add(time.Duration(minutes) * time.Minute)
	}
}

